COLS = ["code_id", "size", "skeleton_hash", "selectors", "proxy_kind", "proxy_target", "code", "std_proxy"]
OLD_SCHEMA = """
CREATE TABLE codes (code_id TEXT PRIMARY KEY, size INTEGER, skeleton_hash TEXT,
    selectors TEXT, proxy_kind TEXT, proxy_target TEXT, code BLOB);
CREATE TABLE addresses (address TEXT PRIMARY KEY, code_id TEXT, block INTEGER);
CREATE TABLE progress (key TEXT PRIMARY KEY, block INTEGER);
CREATE TABLE seeds (address TEXT PRIMARY KEY, code_id TEXT, label TEXT);
CREATE TABLE ledger (day TEXT, method TEXT, credits INTEGER);
