    chk("Fingerprint Code 5: keys", sorted(w.keys()), KEYS)
    chk("Fingerprint Code 5: std_proxy is a bool", (type(a["std_proxy"]), type(w["std_proxy"])), (bool, bool))
    chk("Fingerprint Code 4: fingerprint(b'')", fingerprint(b""), None)
