    w = fingerprint(load_hex("code_weth9.hex"))
    a = fingerprint(load_hex("code_proxy_seed_0c010533.hex")); b = fingerprint(load_hex("code_proxy_046eee2c.hex"))
    chk("Score Fingerprints 2: seed proxy vs 046eee2c, vs weth9", (score_fingerprints(a, b), score_fingerprints(a, w)), (0.0, 0.0))
    w2 = copy.deepcopy(w); w2["std_proxy"] = True
