    chk("Score Fingerprints 3: weth9 vs std_proxy-True copy; seed proxy forced False vs itself", (score_fingerprints(w, w2), score_fingerprints(a2, copy.deepcopy(a2))), (0.0, 1.0))
    chk("Score Fingerprints 4: None cases", (score_fingerprints(None, w), score_fingerprints(w, None), score_fingerprints(None, None)), (0.0, 0.0, 0.0))
