    chk("Store 7: (fingerprints, std_proxy True)", (len(fps), sum(1 for f in fps if f["std_proxy"] is True)), (130, 17))
    bad_eq = [f["code_id"] for f in fps if f != fingerprint(byid[f["code_id"]])]
