    seen = set()
    for a, code in pairs:
        f = fingerprint(code)
        if f["code_id"] not in seen:
            seen.add(f["code_id"])
            c.execute("INSERT INTO codes VALUES (?, ?, ?, ?, ?, ?, ?)", (f["code_id"], f["size"], f["skeleton_hash"], json.dumps(f["selectors"]), f["proxy"]["kind"] if f["proxy"] else None, f["proxy"]["target"] if f["proxy"] else None, sqlite3.Binary(code)))
