    s = Store(p); got = s.fingerprints(); addr = s.addresses_of("8b5db55fa9ab3b9527508d4abe0b39eb588bf310270c8e04b3f38214e8ba63b4"); s.close()
    chk("Store 8: migrated columns", cols(p), COLS)
    chk("Store 8: migrated index", index_cols(p), ["code_id"])
    chk("Store 8: rows with std_proxy NULL after open", nulls(p), 0)
    chk("Store 8: migrated fingerprints() == fresh (len, std True, equal)", (len(got), sum(1 for f in got if f["std_proxy"] is True), got == want), (130, 17, True))
    chk("Store 8: addresses_of 8b5db55f... after migration", len(addr), 4)
    s = Store(p); again = s.fingerprints(); s.close()
    chk("Store 8: second open keeps fingerprints()", again == want, True)
    c = sqlite3.connect(p); c.execute("UPDATE codes SET std_proxy = NULL"); c.commit(); c.close()
    s = Store(p); got2 = s.fingerprints(); s.close()
    chk("Store 9: NULL rows after reopen", nulls(p), 0)
    chk("Store 9: fingerprints() after the NULL fill == fresh", got2 == want, True)
run("fingerprint code", fp_code); run("score", score); run("schema", schema)
res = []
run("block fingerprints", lambda: res.append(block_fps()))
if res:
    run("migration", lambda: migrate(res[0][0], res[0][1]))
print("\n".join(bad) if bad else "probe OK: %s" % LABEL)
sys.exit(1 if bad else 0)
