import os, tempfile
from unittest import mock
import ethsc.cluster as C
from ethsc.cluster import find_similar, match_watchlist, recheck_watchlist, build_clusters
from ethsc.fingerprint import similarity
from ethsc.store import Store
from tests.helpers import load_hex, block_codes
UNI = "0xb4e16d0168e52d35cacd2c6185b44281ec28c9dc"
BELLE = "0x34c6211621f2763c60eb007dc2ae91090a2d22f6"
COPIES = [("code_belle_copy_1807090d.hex", "0x1807090dd15a6f58e00fd769e32ebf20ee610385"),
          ("code_belle_copy_2141be5f.hex", "0x2141be5f2afa674c94167ab167a478a56cb539f5"),
          ("code_belle_copy_46cadea5.hex", "0x46cadea509dc3d3c96a11fb61ab8b222f5238f0a"),
          ("code_belle_copy_6411bed8.hex", "0x6411bed82614b91ef655d82486e0bd3a13d2eb8c")]
FS1 = [("0x22052a1a0f5a3d2839d71c458f177e68b0e73963", 1.0), ("0x2621cc0b3f3c079c1db0e80794aa24976f0b9e3c", 1.0),
       ("0x3041cbd36888becc7bbcbc0045e3b1f144466f5f", 1.0), ("0xcf6daab95c476106eca715d48de4b13287ffdeaa", 26.0 / 32.0)]
def newstore():
    return Store(os.path.join(tempfile.mkdtemp(prefix="p11-probe-"), "e.sqlite"))
def bstore():
    s = newstore()
    for a, t in sorted(block_codes().items()):
        s.put_address(a, None if t == "0x" else s.put_code(bytes.fromhex(t[2:])), 26077729)
    return s
def belle_store():
    s = newstore()
    s.put_address(BELLE, s.put_code(load_hex("code_belle.hex")), 1)
    for f, a in COPIES:
        s.put_address(a, s.put_code(load_hex(f)), 1)
    return s
def alerts(lst):
    return [(x["address"], x["seed_address"], x["label"], x["score"]) for x in lst]
def old_recheck(store, min_score=0.8):
    out = []
    for seed in store.seeds():
        sc = store.code_by_id(seed["code_id"])
        for fp in store.fingerprints():
            score = similarity(sc, store.code_by_id(fp["code_id"]))
            if score >= min_score:
                for a in store.addresses_of(fp["code_id"]):
                    if a != seed["address"]:
                        out.append((a, seed["address"], seed["label"], score))
    return sorted(out, key=lambda x: (x[0], -x[3], x[1]))
class NoCode(object):
    def __init__(self, s):
        self._s = s
    def __getattr__(self, name):
        if name == "code_by_id":
            raise AssertionError("code_by_id called")
        return getattr(self._s, name)
def boom(*a, **k):
    raise AssertionError("similarity called")
def examples():
    s = bstore(); s.add_seed(UNI, "UniV2 pair seed")
    chk("Find Similar 1", find_similar(s, UNI), FS1)
    chk("Find Similar 1 upper-case query", find_similar(s, UNI.upper().replace("0X", "0x")), FS1)
