    out = []
    for n in ast.walk(tree_of(path)):
        if isinstance(n, ast.Attribute) and n.attr.startswith("_") \
                and not n.attr.startswith("__"):
            out.append("%s line %d reads a private attribute .%s; %s"
                       % (path, n.lineno, n.attr, why))
    return out


